// Global styles and theme
export const FONT_BODY = "'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif";
export const FONT_DISPLAY = "'Fraunces', Georgia, serif";

export const globalStyles = `
  @import url('https://fonts.googleapis.com/css2?family=Fraunces:wght@500;700;900&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap');

  * { box-sizing: border-box; }
  body { margin: 0; }

  @keyframes float {
    0%, 100% { transform: translateY(0) rotate(0); }
    50% { transform: translateY(-20px) rotate(8deg); }
  }
  @keyframes slideUp {
    from { opacity: 0; transform: translateY(20px); }
    to { opacity: 1; transform: translateY(0); }
  }
  @keyframes pop {
    0% { transform: scale(0.8); opacity: 0; }
    80% { transform: scale(1.05); }
    100% { transform: scale(1); opacity: 1; }
  }
  @keyframes shimmer {
    0% { background-position: -200% 0; }
    100% { background-position: 200% 0; }
  }
  .grade-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 12px 24px rgba(0,0,0,0.08);
  }
  .skill-card:hover {
    transform: translateX(4px);
    box-shadow: 0 4px 16px rgba(0,0,0,0.06);
  }
  input:focus, button:focus-visible {
    outline: 3px solid #9B5DE544;
    outline-offset: 2px;
  }
  button { font-family: inherit; }

  @media (max-width: 768px) {
    .grade-card { min-width: 0 !important; }
  }
`;

export const baseStyles = {
  app: {
    minHeight: '100vh',
    fontFamily: FONT_BODY,
    background: 'linear-gradient(180deg, #FAFBFF 0%, #F5F3FF 100%)',
    color: '#1F2937',
    display: 'flex',
    flexDirection: 'column',
  },
  main: { flex: 1, paddingBottom: 40 },
  container: { maxWidth: 1200, margin: '0 auto', padding: '32px 24px' },

  // Header
  header: {
    background: 'rgba(255,255,255,0.85)',
    backdropFilter: 'blur(12px)',
    borderBottom: '1px solid #E5E7EB',
    position: 'sticky',
    top: 0,
    zIndex: 50,
  },
  headerInner: {
    maxWidth: 1200,
    margin: '0 auto',
    padding: '14px 24px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    gap: 16,
    flexWrap: 'wrap',
  },
  logo: {
    display: 'flex',
    alignItems: 'center',
    gap: 12,
    background: 'transparent',
    border: 'none',
    cursor: 'pointer',
  },
  logoIcon: {
    width: 40,
    height: 40,
    borderRadius: 12,
    background: 'linear-gradient(135deg, #9B5DE5 0%, #F15BB5 100%)',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    color: 'white',
    boxShadow: '0 4px 12px rgba(155,93,229,0.3)',
  },
  logoText: { fontFamily: FONT_DISPLAY, fontSize: 22, fontWeight: 900, color: '#1F2937', lineHeight: 1 },
  logoTag: { fontSize: 11, color: '#6B7280', marginTop: 2, fontWeight: 500 },

  // Buttons
  primaryBtn: {
    padding: '12px 24px',
    borderRadius: 12,
    border: 'none',
    background: '#9B5DE5',
    color: 'white',
    fontWeight: 600,
    cursor: 'pointer',
    display: 'inline-flex',
    alignItems: 'center',
    gap: 8,
    fontSize: 14,
    transition: 'all 0.2s',
    boxShadow: '0 4px 12px rgba(155,93,229,0.3)',
  },
  secondaryBtn: {
    padding: '10px 20px',
    borderRadius: 10,
    border: '2px solid #E5E7EB',
    background: 'white',
    color: '#1F2937',
    fontWeight: 600,
    cursor: 'pointer',
    display: 'inline-flex',
    alignItems: 'center',
    gap: 8,
    fontSize: 14,
    transition: 'all 0.2s',
  },
  iconBtn: {
    background: 'transparent',
    border: 'none',
    cursor: 'pointer',
    padding: 8,
    borderRadius: 8,
    color: '#1F2937',
    transition: 'all 0.2s',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
  },

  // Cards
  card: {
    background: 'white',
    borderRadius: 16,
    border: '1px solid #E5E7EB',
    padding: 24,
    boxShadow: '0 1px 3px rgba(0,0,0,0.05)',
    transition: 'all 0.2s',
  },

  // Footer
  footer: {
    background: 'rgba(255,255,255,0.5)',
    borderTop: '1px solid #E5E7EB',
    padding: '24px',
    textAlign: 'center',
